package servicio;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import dao.*;import negocio.*;
class ProcesamientoOrdenPagoServiceTest {
 private OrdenPago orden(){OrdenPago o=new OrdenPago();o.setId(1);o.setReservaId(9);o.setImporte(new BigDecimal("6250.00"));o.setClaveIdempotencia("k");o.setEstado(EstadoOrdenPago.PROCESANDO);return o;}
 private EventoPago evento(){EventoPago e=new EventoPago();e.setOrdenPagoId(1);e.setProveedor(ProveedorPago.MERCADO_PAGO);e.setEventoExternoId("evt-1");e.setTipo("payment.updated");e.setPayloadHash("a".repeat(64));e.setFirmaValida(true);return e;}
 @Test void eventoAprobadoGeneraPagoAuditableUnaSolaVez(){OrdenPagoDAO ordenes=mock(OrdenPagoDAO.class);EventoPagoDAO eventos=mock(EventoPagoDAO.class);PagoService pagos=mock(PagoService.class);OrdenPago orden=orden();when(eventos.registrarSiNuevo(any())).thenReturn(true);when(ordenes.buscar(1)).thenReturn(orden);when(ordenes.actualizarEstado(1,0,EstadoOrdenPago.APROBADA,"mp-1")).thenReturn(true);ProcesamientoOrdenPagoService service=new ProcesamientoOrdenPagoService(ordenes,eventos,pagos);assertTrue(service.procesarAprobacion(evento(),"mp-1"));ArgumentCaptor<Pago> captor=ArgumentCaptor.forClass(Pago.class);verify(pagos,times(1)).guardar(captor.capture());Pago creado=captor.getValue();assertEquals(1L,creado.getOrdenPagoId());assertEquals(9L,creado.getReservaId());assertEquals(OrigenAcreditacion.WEBHOOK,creado.getOrigenAcreditacion());assertEquals(EstadoPago.ACREDITADO,creado.getEstado());verify(eventos).marcarProcesado(anyLong(),eq("Acreditación registrada."));}
 @Test void eventoDuplicadoNoGeneraPago(){OrdenPagoDAO ordenes=mock(OrdenPagoDAO.class);EventoPagoDAO eventos=mock(EventoPagoDAO.class);PagoService pagos=mock(PagoService.class);when(eventos.registrarSiNuevo(any())).thenReturn(false);ProcesamientoOrdenPagoService service=new ProcesamientoOrdenPagoService(ordenes,eventos,pagos);assertFalse(service.procesarAprobacion(evento(),"mp-1"));verifyNoInteractions(ordenes,pagos);}
 @Test void rechazaFirmaInvalida(){OrdenPagoDAO ordenes=mock(OrdenPagoDAO.class);EventoPagoDAO eventos=mock(EventoPagoDAO.class);PagoService pagos=mock(PagoService.class);EventoPago e=evento();e.setFirmaValida(false);assertThrows(IllegalArgumentException.class,()->new ProcesamientoOrdenPagoService(ordenes,eventos,pagos).procesarAprobacion(e,"x"));verifyNoInteractions(ordenes,eventos,pagos);}
}
